# -*- coding: utf-8 -*-
"""퍼스널 OS — 🔑 로그인 연장 업데이트 (퍼스널OS_설치키트_261116 기준, 2026-11-16)
클로드 로그인은 약 4주마다 끝난다. 이 업데이트를 돌리면:
  ① 앱 위쪽 사용량 옆에 '로그인 N일' + 누르면 연장 창(브라우저 '허용' 한 번, 휴대폰에서도 승인 가능)
  ② 만료 7·3·1일 전 휴대폰 알림 + 오늘 할 일 (3시간마다 확인)
  ③ 자동 예약 등록(맥 LaunchAgents / 윈도우 작업 스케줄러)
  ④ 앱 서버 다시 띄우기(답이 끝난 뒤)
고치기 전 원본은 ~/퍼스널OS/.os_데이터/백업_로그인연장_<시각>/ 에 남긴다. 두 번 돌려도 안전하다.
    python3 login_renew_update.py
"""
import base64, json, os, py_compile, re, shutil, subprocess, sys, time

for _s in (sys.stdout, sys.stderr):
    try:
        _s.reconfigure(encoding="utf-8", errors="replace")   # 윈도우 콘솔(cp949)에서 이모지로 멈추지 않게
    except Exception:
        pass
P = json.loads(base64.b64decode("").decode("utf-8"))
HOME = os.path.expanduser("~")
OS_DIR = os.path.join(HOME, "퍼스널OS")
DATA = os.path.join(OS_DIR, ".os_데이터")
WIN = os.name == "nt"
SRV = os.path.join(OS_DIR, "elvin_server.py")
WEB = os.path.join(OS_DIR, "elvin_web.html")
out = []
def say(t): out.append(t); print(t, flush=True)

if not (os.path.exists(SRV) and os.path.exists(WEB)):
    print("❌ ~/퍼스널OS/elvin_server.py · elvin_web.html 을 찾지 못했습니다. 퍼스널 OS 가 설치된 컴퓨터에서 돌려 주세요."); sys.exit(1)

bk = os.path.join(DATA, "백업_로그인연장_" + time.strftime("%y%m%d_%H%M"))
os.makedirs(bk, exist_ok=True)
shutil.copy2(SRV, bk); shutil.copy2(WEB, bk)
say("📦 원본 보관: " + bk)

# ── ① 서버
s = open(SRV, encoding="utf-8").read()
if "def login_status(" in s:
    say("✔ 서버: 이미 들어 있음")
else:
    try:
        k = s.index("\ndef side_thread(")
        s = s[:k + 1] + P["funcs"] + s[k + 1:]
        m = re.search(r'\n( +)elif path == "/api/usage":', s)
        ind = m.group(1)
        s = s[:m.start() + 1] + "\n".join(ind + l if l.strip() else l for l in P["get"].split("\n")) + "\n" + s[m.start() + 1:]
        m = re.search(r'\n( +)if path == "/api/push/subscribe":', s)
        ind = m.group(1)
        s = s[:m.start() + 1] + "\n".join(ind + l if l.strip() else l for l in P["post"].split("\n")) + "\n" + s[m.start() + 1:]
        if not re.search(r"^import re\b", s, re.M):
            s = "import re\n" + s
        tmp = SRV + ".새판"
        open(tmp, "w", encoding="utf-8").write(s)
        py_compile.compile(tmp, doraise=True)
        os.replace(tmp, SRV)
        say("✔ 서버: 로그인 확인·연장 기능 추가")
    except Exception as e:
        say("❌ 서버를 고치지 못했습니다(원본 그대로): %s" % str(e)[:200])
        say("   → 매니저가 백업 폴더의 원본과 비교해 직접 넣어 주세요: login_status / login_renew / login_code 함수, GET /api/login/status, POST /api/login/renew · /api/login/code")
        sys.exit(2)

# ── ② 화면
w = open(WEB, encoding="utf-8").read()
if 'id="lgBar"' in w:
    say("✔ 화면: 이미 들어 있음")
else:
    k = w.rindex("</body>")
    w = w[:k] + P["web"] + "\n" + w[k:]
    open(WEB, "w", encoding="utf-8").write(w)
    say("✔ 화면: 사용량 옆 '로그인 N일' · 연장 창 추가")

# ── ③ 만료 알림 스크립트
name = "매니저"
try:
    c = json.load(open(os.path.join(OS_DIR, "설정.json"), encoding="utf-8"))
    name = (c.get("실장") or c.get("직함") or name).strip() or name
except Exception:
    pass
auto = os.path.join(OS_DIR, "부서", "00_비서실", "자동")
os.makedirs(auto, exist_ok=True)
rp = os.path.join(auto, "로그인연장.py")
open(rp, "w", encoding="utf-8").write(P["renew"].replace("{{실장}}", name))
say("✔ 만료 알림 스크립트: " + rp)

# ── ④ 자동 예약 (3시간마다)
py = sys.executable
TEST = "--시험" in sys.argv
if TEST:
    say("(시험: 예약 건너뜀)")
elif WIN:
    pyw = os.path.join(os.path.dirname(py), "pythonw.exe")
    pyw = pyw if os.path.exists(pyw) else py
    tr = '"%s" -X utf8 "%s"' % (pyw, rp)
    r = subprocess.run(["schtasks", "/Create", "/F", "/TN", "PersonalOS\\loginrenew", "/TR", tr, "/SC", "HOURLY", "/MO", "3"], capture_output=True, text=True, errors="replace")
    say("✔ 작업 스케줄러 등록" if r.returncode == 0 else "⚠ 작업 스케줄러 등록 실패: " + (r.stderr or r.stdout)[-150:])
else:
    la = os.path.join(HOME, "Library", "LaunchAgents"); os.makedirs(la, exist_ok=True)
    pl = os.path.join(la, "com.personalos.loginrenew.plist")
    open(pl, "w", encoding="utf-8").write(
        '<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
        '<plist version="1.0"><dict><key>Label</key><string>com.personalos.loginrenew</string>'
        '<key>ProgramArguments</key><array><string>%s</string><string>%s</string></array>'
        '<key>WorkingDirectory</key><string>%s</string>'
        '<key>EnvironmentVariables</key><dict><key>PATH</key><string>%s/.local/bin:/usr/local/bin:/opt/homebrew/bin:/usr/bin:/bin:/usr/sbin:/sbin</string><key>LANG</key><string>ko_KR.UTF-8</string></dict>'
        '<key>RunAtLoad</key><true/><key>StartInterval</key><integer>10800</integer>'
        '<key>StandardOutPath</key><string>%s/loginrenew.log</string><key>StandardErrorPath</key><string>%s/loginrenew.log</string>'
        '</dict></plist>\n' % (py, rp, OS_DIR, HOME, DATA, DATA))
    uid = str(os.getuid())
    subprocess.run(["launchctl", "bootout", "gui/" + uid, pl], capture_output=True)
    r = subprocess.run(["launchctl", "bootstrap", "gui/" + uid, pl], capture_output=True, text=True, errors="replace")
    if r.returncode != 0:
        r = subprocess.run(["launchctl", "load", "-w", pl], capture_output=True, text=True, errors="replace")
    say("✔ 자동 예약 등록(3시간마다)" if r.returncode == 0 else "⚠ 자동 예약 등록 실패: " + (r.stderr or "")[-150:])

# ── 지금 남은 기간
try:
    import importlib.util
    spec = importlib.util.spec_from_file_location("lr", rp); m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
    st = m.status()
    if st.get("loggedIn") is False:
        say("🔑 지금 로그인: 풀려 있음 → 앱에서 '로그인 연장'을 눌러 주세요")
    elif st.get("days") is not None:
        say("🔑 지금 로그인: 약 %d일 남음 (%s 까지)" % (int(st["days"]), (st.get("expiresAt") or "")[:10]))
except Exception:
    pass

# ── ⑤ 서버 다시 띄우기 (답이 끝난 뒤)
if TEST:
    pass
elif WIN:
    rs = os.path.join(OS_DIR, ".os_키트", "윈도우_서버재시작.py")
    if os.path.exists(rs):
        subprocess.Popen([py, rs]); say("🔄 25초 뒤(답이 끝난 뒤) 앱 서버를 다시 띄웁니다")
    else:
        say("⚠ 앱 서버를 다시 띄워 주세요(컴퓨터 재시작도 됩니다)")
else:
    d = os.path.join(OS_DIR, "부서", "00_비서실")
    ft, rs = os.path.join(d, "떼어내기.py"), os.path.join(d, "서버재시작.sh")
    if os.path.exists(ft) and os.path.exists(rs):
        subprocess.Popen([py, ft, rs]); say("🔄 25초 뒤(답이 끝난 뒤) 앱 서버를 다시 띄웁니다")
    else:
        subprocess.Popen(["/bin/bash", "-c", "sleep 30; launchctl kickstart -k gui/%s/com.personalos.server" % os.getuid()], start_new_session=True)
        say("🔄 30초 뒤 앱 서버를 다시 띄웁니다")
say("✅ 끝 — 서버가 다시 켜진 뒤 앱을 새로고침하면 위쪽 사용량 옆에 '로그인 N일'이 보입니다.")
